-- Read-only calendar integrity checks, not a concurrency certification.
SELECT 'calendar_tenant_module',COUNT(*) FROM institution_lesson l LEFT JOIN formative_module m ON m.institution_id=l.institution_id AND m.version_id=l.version_id AND m.id=l.module_id WHERE m.id IS NULL;
SELECT 'calendar_time',COUNT(*) FROM institution_lesson WHERE ends_at<=starts_at OR end_utc<=start_utc OR SECOND(starts_at)<>0 OR SECOND(ends_at)<>0;
SELECT 'calendar_completed',COUNT(*) FROM institution_lesson WHERE (status='Completed' AND (delivered_minutes IS NULL OR confirmed_at_utc IS NULL)) OR (status<>'Completed' AND delivered_minutes IS NOT NULL);
SELECT 'calendar_published_overlap',COUNT(*) FROM institution_lesson a JOIN institution_lesson b ON b.institution_id=a.institution_id AND b.id>a.id AND (a.class_id=b.class_id OR a.teacher_id=b.teacher_id) AND a.start_utc<b.end_utc AND b.start_utc<a.end_utc WHERE a.publication='Published' AND b.publication='Published' AND a.status<>'Cancelled' AND b.status<>'Cancelled';
SELECT 'calendar_occupancy',COUNT(*) FROM institution_lesson l WHERE (l.publication='Published' AND l.status<>'Cancelled' AND (SELECT COUNT(*) FROM institution_calendar_occupancy o WHERE o.institution_id=l.institution_id AND o.lesson_id=l.id AND o.event_id=l.event_id)<>2) OR ((l.publication<>'Published' OR l.status='Cancelled') AND EXISTS(SELECT 1 FROM institution_calendar_occupancy o WHERE o.institution_id=l.institution_id AND o.lesson_id=l.id));
